"""Generate src/CaTTExp/Dag/Trie.agda: B-ary tries keyed by naturals.
The B-fold boilerplate is mechanical, so it is generated."""
import os
B = 4
FUEL = 16      # B ** FUEL keys are reachable
SUCB = lambda v: "(suc " * B + v + ")" * B
cs = ' '.join('c%d' % i for i in range(B))
us = ' '.join('_' for i in range(B))
ls = ' '.join('tleaf' for i in range(B))
ps = ' , '.join('p%d' % i for i in range(B))
out = []
w = out.append
w('''------------------------------------------------------------------------
-- 4-ary tries keyed by natural numbers (generated by
-- tools/gen_dag_trie.py; do not edit).
--
-- A tnode stores at most one entry *together with its key*, and lookup
-- returns an entry only when the stored key equals the query. So the
-- soundness facts needed by the DAG checker are independent of how keys
-- are laid out:
--   lookup-All : All P t → lookupT k t ≡ just x → P k x
--   allT-All   : T (allT p t) → All (λ k x → T (p k x)) t
--   insert-All : All P t → P k x → All P (insert k x t)
-- Where keys are placed only matters for completeness (finding what
-- was inserted), never for soundness.
------------------------------------------------------------------------
open import CaTTExp.Prelude
open import Agda.Builtin.Nat using (div-helper; mod-helper)
open import Agda.Builtin.Strict using (primForce; primForceLemma)

module CaTTExp.Dag.Trie where

Entry : Set → Set
Entry A = Σ Nat (λ _ → A)

data Trie (A : Set) : Set where
  tleaf : Trie A
  tnode : Maybe (Entry A) → %s → Trie A

dig : Nat → Nat
dig k = mod-helper 0 %d k %d

quo : Nat → Nat
quo k = div-helper 0 %d k %d

module _ {A : Set} where
''' % (' → '.join(['Trie A'] * B), B - 1, B - 1, B - 1, B - 1))
w('  pick : Nat → Trie A → Trie A')
w('  pick _ tleaf = tleaf')
for i in range(B):
    w('  pick %d (tnode _ %s) = c%d' % (i, cs, i))
w('  pick _ (tnode _ %s) = tleaf' % us)
w('')
w('  slot : Nat → Maybe (Entry A) → Maybe A')
w('  slot o nothing        = nothing')
w('  slot o (just (k , x)) = if k ==ℕ o then just x else nothing')
w('')
w('  look : Nat → Nat → Nat → Trie A → Maybe A')
w('  look zero    o k       t = nothing')
w('  look (suc f) o zero    tleaf = nothing')
w('  look (suc f) o zero    (tnode m %s) = slot o m' % us)
w('  look (suc f) o (suc k) t = look f o (quo (suc k)) (pick (dig (suc k)) t)')
w('')
w('  lookupT : Nat → Trie A → Maybe A')
w('  lookupT k t = look %d k k t' % FUEL)
w('')
w('  setc : Nat → (Trie A → Trie A) → Trie A → Trie A')
for i in range(B):
    w('  setc %d f tleaf = primForce (f tleaf) (λ x → tnode nothing %s)' % (i, ' '.join('x' if j == i else 'tleaf' for j in range(B))))
for i in range(B):
    w('  setc %d f (tnode m %s) = primForce (f c%d) (λ x → tnode m %s)' % (i, cs, i, ' '.join('x' if j == i else 'c%d' % j for j in range(B))))
w('  setc _ f t = t')
w('')
w('  setm : Maybe (Entry A) → Trie A → Trie A')
w('  setm m tleaf = tnode m %s' % ls)
w('  setm m (tnode _ %s) = tnode m %s' % (cs, cs))
w('')
w('  ins : Nat → Nat → Nat → A → Trie A → Trie A')
w('  ins zero    o k       x t = t')
w('  ins (suc f) o zero    x t = setm (just (o , x)) t')
w('  ins (suc f) o (suc k) x t = setc (dig (suc k)) (ins f o (quo (suc k)) x) t')
w('')
w('  insert : Nat → A → Trie A → Trie A')
w('  insert k x t = ins %d k k x t' % FUEL)
w('')
w('  allM : (Nat → A → Bool) → Maybe (Entry A) → Bool')
w('  allM p nothing        = true')
w('  allM p (just (k , x)) = p k x')
w('')
w('  allT : (Nat → A → Bool) → Trie A → Bool')
w('  allT p tleaf = true')
w('  allT p (tnode m %s) = allM p m ∧ %s' % (cs, ' ∧ '.join('allT p c%d' % i for i in range(B))))
w('')
w('  ------------------------------------------------------------------')
w('  -- All')
w('')
w('  AllM : (Nat → A → Set) → Maybe (Entry A) → Set')
w('  AllM P nothing        = ⊤')
w('  AllM P (just (k , x)) = P k x')
w('')
w('  All : (Nat → A → Set) → Trie A → Set')
w('  All P tleaf = ⊤')
w('  All P (tnode m %s) = AllM P m × %s' % (cs, ' × '.join('All P c%d' % i for i in range(B))))
w('')
w('  module _ {P : Nat → A → Set} where')
w('    pick-All : ∀ d t → All P t → All P (pick d t)')
w('    pick-All _ tleaf _ = tt')
for i in range(B):
    w('    pick-All %d (tnode _ %s) (_ , %s) = p%d' % (i, cs, ps, i))
w('    pick-All %s (tnode _ %s) _ = tt' % (SUCB('d'), us))
w('')
w('    slot-All : ∀ o m {x} → AllM P m → slot o m ≡ just x → P o x')
w('    slot-All o nothing _ ()')
w('    slot-All o (just (k , y)) p e with k ==ℕ o in eq')
w('    slot-All o (just (k , y)) p refl | true with ==ℕ-sound k o (subst T (sym eq) tt)')
w('    ... | refl = p')
w('    slot-All o (just (k , y)) p () | false')
w('')
w('    look-All : ∀ f o k t {x} → All P t → look f o k t ≡ just x → P o x')
w('    look-All zero    o k       t p ()')
w('    look-All (suc f) o zero    tleaf p ()')
w('    look-All (suc f) o zero    (tnode m %s) (pm , _) e = slot-All o m pm e' % us)
w('    look-All (suc f) o (suc k) t p e =')
w('      look-All f o (quo (suc k)) (pick (dig (suc k)) t) (pick-All (dig (suc k)) t p) e')
w('')
w('    lookup-All : ∀ {k t x} → All P t → lookupT k t ≡ just x → P k x')
w('    lookup-All {k} {t} p e = look-All %d k k t p e' % FUEL)
w('')
w('    tleaf-All : All P tleaf')
w('    tleaf-All = tt')
w('')
w('    setc-All : ∀ d f t → All P t → (∀ c → All P c → All P (f c)) → All P (setc d f t)')
for i in range(B):
    w('    setc-All %d f tleaf _ h = subst (All P) (sym (primForceLemma (f tleaf) (λ x → tnode nothing %s))) (%s)' % (i, ' '.join('x' if j == i else 'tleaf' for j in range(B)), ' , '.join(['tt'] + [('h tleaf tt' if j == i else 'tt') for j in range(B)])))
for i in range(B):
    w('    setc-All %d f (tnode m %s) (pm , %s) h = subst (All P) (sym (primForceLemma (f c%d) (λ x → tnode m %s))) (%s)' % (i, cs, ps, i, ' '.join('x' if j == i else 'c%d' % j for j in range(B)), ' , '.join(['pm'] + [('h c%d p%d' % (j, j) if j == i else 'p%d' % j) for j in range(B)])))
w('    setc-All %s f tleaf p h = p' % SUCB('d'))
w('    setc-All %s f (tnode _ %s) p h = p' % (SUCB('d'), us))
w('')
w('    setm-All : ∀ m t → AllM P m → All P t → All P (setm m t)')
w('    setm-All m tleaf pm _ = %s' % ' , '.join(['pm'] + ['tt'] * B))
w('    setm-All m (tnode _ %s) pm (_ , %s) = %s' % (cs, ps, ' , '.join(['pm'] + ['p%d' % i for i in range(B)])))
w('')
w('    ins-All : ∀ f o k x t → All P t → P o x → All P (ins f o k x t)')
w('    ins-All zero    o k       x t p q = p')
w('    ins-All (suc f) o zero    x t p q = setm-All (just (o , x)) t q p')
w('    ins-All (suc f) o (suc k) x t p q =')
w('      setc-All (dig (suc k)) (ins f o (quo (suc k)) x) t p')
w('        (λ c pc → ins-All f o (quo (suc k)) x c pc q)')
w('')
w('    insert-All : ∀ {k x t} → All P t → P k x → All P (insert k x t)')
w('    insert-All {k} {x} {t} p q = ins-All %d k k x t p q' % FUEL)
w('')
w('  All-map : ∀ {P Q : Nat → A → Set} → (∀ k x → P k x → Q k x) → ∀ t → All P t → All Q t')
w('  All-map g tleaf _ = tt')
w('  All-map g (tnode nothing %s) (_ , %s) = %s' % (cs, ps, ' , '.join(['tt'] + ['All-map g c%d p%d' % (i, i) for i in range(B)])))
w('  All-map g (tnode (just (k , x)) %s) (pm , %s) = %s' % (cs, ps, ' , '.join(['g k x pm'] + ['All-map g c%d p%d' % (i, i) for i in range(B)])))

w('')
w('  allM-All : ∀ (p : Nat → A → Bool) m → T (allM p m) → AllM (λ k x → T (p k x)) m')
w('  allM-All p nothing        _ = tt')
w('  allM-All p (just (k , x)) q = q')
w('')
w('  allT-All : ∀ (p : Nat → A → Bool) t → T (allT p t) → All (λ k x → T (p k x)) t')
w('  allT-All p tleaf _ = tt')
# chain: q : T (allM p m ∧ allT p c0 ∧ ... )
w('  allT-All p (tnode m %s) q =' % cs)
terms = ['allM p m'] + ['allT p c%d' % i for i in range(B)]
# build nested let
def proj(k):
    # q_k : T(terms[k] ∧ ... ∧ terms[-1])
    pass
lines = []
cur = 'q'
for k in range(len(terms) - 1):
    lines.append('    let q%d = ∧-snd {%s} %s in' % (k, terms[k], cur))
    cur = 'q%d' % k
res = ['allM-All p m (∧-fst q)']
cur = 'q'
for k in range(1, len(terms)):
    prev = 'q%d' % (k - 1)
    if k < len(terms) - 1:
        res.append('allT-All p c%d (∧-fst %s)' % (k - 1, prev))
    else:
        res.append('allT-All p c%d %s' % (k - 1, prev))
for l in lines:
    w(l)
w('    ' + ' , '.join(res))
w('')
path = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'src', 'CaTTExp', 'Dag', 'Trie.agda')
open(path, 'w').write('\n'.join(out) + '\n')
print('wrote', path)
